// Walkthroughs for the athlete-more family (see athlete-more-walkthroughs.js, walkthrough-kit.js and guide-walkthroughs.js), part a. Kept in its own file so two writers can work on one guide without touching the same lines.
// Part a: food, eating too little, training, recovery, a blow to the head, heat, pressure and mental health, abuse in sport, name-image-likeness deals, taxes, endorsements, a business, the prohibited list, the NAIA and amateur status.
// The health walkthroughs here diagnose nothing, give no amounts of medicine and no treatment plan: they say when to stop and get help, point to the official page, and say what to ask a clinician.

const { S, W, OWN } = require("./walkthrough-kit.js");

module.exports = {
  "eating-and-drinking": {
    title: "Eating and drinking well around training",
    topic: "athlete-nutrition", phrase: "eating and drinking well around training as an athlete",
    steps: [
      S("Plan the meal before a workout", "The Academy of Nutrition and Dietetics says to eat about one to four hours before a workout, depending on how your body handles food. It suggests carbohydrates and protein, for example a peanut butter and banana sandwich, or Greek yogurt with berries. It says not to eat right before you exercise, because digestion competes with your muscles.", ["Paper and a pen", "The official page open to read"], "eatrightTiming", "you have written down one meal you could eat one to four hours before your next workout.", [W("Carbohydrates", "foods like bread, rice, fruit and potatoes that give your body quick energy."), W("Protein", "foods like yogurt, eggs, beans and meat that help your muscles rebuild.")]),
      S("Plan your game day eating", "For game day the Academy says to eat a full meal about three hours before, and a small snack 30 minutes to an hour before. It says not to skip lunch. Both the Academy and the NCAA say never to try anything new on a game or race day, because you do not want to find out on that day that a food upsets you.", ["Your game or race time", "Paper and a pen"], "eatrightGameday", "you have written when you will eat your meal and your snack on your next game day, and every food on the list is one you have eaten before.", [W("NCAA", "the National Collegiate Athletic Association, the group that runs most college sports in the United States.")]),
      S("Eat after a hard workout", "After an intense workout the Academy says to try to eat within an hour, again with carbohydrates and protein. The NCAA's 2025 sheet suggests 20 to 40 grams of protein with carbohydrates in a recovery snack. These are rules of thumb. The pages give no amounts for your sport, size or position.", ["A snack you can pack in your bag"], "ncaaFuelRecovery", "you know what snack you will bring to eat within an hour of your hardest workout.", [W("Recovery snack", "food you eat after training so your body can rebuild and refill its energy.")]),
      S("Drink enough, and know the signs", "The Academy says water is usually enough for a workout under an hour, and a sports drink can help in longer sessions. It says fluid loss of more than 2 percent of your body weight harms performance, and that nearly clear urine means you are well hydrated.", ["A water bottle"], "eatrightTiming", "you can say what colour of urine means you are well hydrated, and when a sports drink can help.", [W("Hydrated", "having enough water in your body."), W("Sports drink", "a drink with sugar and salts, made to replace some of what you lose in sweat.")]),
      S("Know the risk of too much plain water", "An older NCAA sheet from 2013 warns that large amounts of plain water after long, hard sweating can cause dangerously low blood sodium. The pages do not set amounts for you, so ask a sports dietitian or athletic trainer how to drink if you sweat a lot.", ["The official page open to read"], "ncaaHydration", "you can say in your own words why a lot of plain water after long, hard sweating can be a problem.", [W("Blood sodium", "the amount of salt in your blood. Too little can make a person very sick.")]),
      S("Write down what works for you", OWN + "For one week, write down what you ate and drank before and after each workout, and how you felt. This gives you real facts to bring to a dietitian, and it shows you which foods sit well with you before you need them on game day.", ["A notebook or the notes on your phone", "A pen"], null, "you have a page with seven days of notes, or a plan to start one tomorrow.", []),
      S("Ask a sports dietitian for your own plan", "The pages above give no amounts for your sport, size or position. The NCAA says a registered dietitian who specializes in sports, which it calls a board certified specialist in sports dietetics, can set a plan for you. Ask your school, club or doctor to point you to one, and bring your notes.", ["Your notes from the week", "The name of your school or club contact"], "ncaaFuelRecovery", "you know who you will ask to be sent to a sports dietitian, and you have your notes ready.", [W("Dietitian", "a trained food and nutrition professional."), W("Sports dietetics", "the part of nutrition that works with athletes on food for training and competition.")])
    ]
  },

  "under-eating-and-eating-problems": {
    title: "Getting help for eating too little and eating problems in sport",
    topic: "athlete-energy", phrase: "getting help for under-eating and eating problems as an athlete",
    steps: [
      S("Learn what eating too little means", "The National Eating Disorders Association says relative energy deficiency in sport is caused by low energy availability. That means eating too little to support both your training and your body's basic needs. This is not a diagnosis, and I cannot tell you whether it is happening to you. Only a doctor can.", ["The official toolkit open to read"], "nedaToolkit", "you can say in your own words what eating too little for your training means.", [W("RED-S", "relative energy deficiency in sport: a state where an athlete eats too little for the training they do."), W("Low energy availability", "not eating enough to cover both exercise and the body's basic needs.")]),
      S("Read the signs the toolkit lists", "The toolkit lists effects such as menstrual problems, weaker immune function, heart problems, depression or irritability, slower recovery, more injuries and lower strength and endurance. Signs it lists include difficulty taking rest days, training while injured or sick, anxiety or guilt when you cannot train, rigid eating, frequent strains or fractures, feeling cold and dizziness.", ["The official toolkit open to read", "Paper and a pen"], "nedaToolkit", "you have read the lists and put a mark next to any sign you would like to talk about with someone you trust.", []),
      S("Know who checks and treats it", "The toolkit says RED-S needs a full evaluation by a sports medicine physician. It is treated with a physician, a sports dietitian and a mental health provider. It also says early detection of an eating disorder is the strongest predictor of full recovery, and it tells coaches to reassure athletes that asking for help will not put their place on the team at risk.", ["The name of your doctor, team physician or clinic"], "nedaToolkit", "you know the three kinds of professional the toolkit names, and which of them you could reach first.", [W("Sports medicine physician", "a doctor trained to care for the health problems of athletes.")]),
      S("Talk to the team physician if periods stop", "An NCAA sheet says a female athlete who misses three or more periods in a row should talk to the team physician. If you do not have a team physician, a doctor or clinic is the place to start.", ["Notes of when you last had a period", "The name of your team physician or clinic"], "ncaaEnergy", "you have written down when you last had a period and who you will tell.", [W("Team physician", "the doctor who looks after the health of a school or club team.")]),
      S("Call for support, free and private", "ANAD, a charity for eating disorders, lists a helpline at 888-375-7767, Monday to Friday, 9 a.m. to 9 p.m. Central. It is free, you do not need a diagnosis, and it returns messages left outside those hours. SAMHSA's National Helpline, 1-800-662-4357, is open 24 hours a day, and you can text your ZIP code to 435748. If you are in crisis, call or text 988.", ["A phone", "Paper to write the numbers on"], "anadGetHelp", "you have the numbers written down where you can find them, or you have made the call.", [W("ANAD", "a charity that gives free support to people who have a difficult relationship with eating or body image."), W("SAMHSA", "the United States government agency for mental health and substance use help.")]),
      S("Try the free screening and search", "The National Eating Disorders Association's get-help page now offers a free, confidential screening tool, a search for treatment, and free and low-cost support. It lists no helpline. A screening tool is not a diagnosis. Bring any result you get to a doctor.", ["A phone or computer"], "nedaGetHelp", "you have seen the screening tool and the treatment search on the page.", [W("Screening tool", "a short set of questions that shows whether you should talk to a professional. It does not give a diagnosis.")])
    ]
  },

  "how-much-to-train": {
    title: "Working out how much to train, and strength training for young athletes",
    topic: "athlete-training", phrase: "working out how much training an athlete needs",
    steps: [
      S("Know what these numbers are", "The CDC pages give general health guidelines. They are not training loads for a competitive athlete, and the pages give no sets, repetitions or weekly plan for a sport. A coach or athletic trainer who knows your sport can set the plan.", ["The official CDC page open to read"], "cdcPhysicalActivity", "you can say that these numbers are for health in general and not a plan for your sport.", [W("CDC", "the Centers for Disease Control and Prevention, a United States health agency."), W("Guideline", "advice on how much activity is good for health.")]),
      S("Find the numbers for children and teens", "The CDC says children and teens aged 6 to 17 need at least 60 minutes a day of moderate to vigorous activity, mostly aerobic. Vigorous activity, muscle strengthening and bone strengthening should each happen on at least 3 days a week.", ["Your age, or your child's age"], "cdcChildActivity", "you have found your age group and can say the minutes a day and the days a week.", [W("Aerobic", "activity that makes your heart and breathing work harder for a while, like running or swimming."), W("Vigorous", "hard enough that you can only say a few words before you need a breath.")]),
      S("Find the numbers for adults", "The CDC says adults aged 18 to 64 need at least 150 minutes a week of moderate activity, plus muscle strengthening on at least 2 days a week.", ["Paper and a pen"], "cdcPhysicalActivity", "you can say the minutes a week and the days a week of muscle strengthening for adults.", [W("Muscle strengthening", "exercise that makes your muscles work against weight or resistance, like lifting or push-ups.")]),
      S("Learn the advice on strength training for young people", "The American Academy of Pediatrics says children of all ages can benefit from strength training with proper supervision and good technique, combined with aerobic training and dynamic warm-ups. It says children with uncontrolled high blood pressure, uncontrolled seizures, certain heart conditions or a history of chemotherapy should see a medical professional first.", ["The official page open to read"], "aapResistance", "you can say that strength training for young people needs supervision, good technique, and a doctor first if one of the listed conditions applies.", [W("Dynamic warm-up", "moving exercises, like gentle jogging and arm circles, that get the body ready for hard work.")]),
      S("Know the older advice on heavy lifting", "An older page from 2009 says explosive or heavy Olympic-style lifts should wait until after the growth spurt. Before puberty, it advises light weights with more repetitions. It says most serious injuries happened with unsupervised home equipment. The page is old, so ask a coach or doctor whether it still applies.", ["The official page open to read"], "aapWeightRisk", "you know the page is from 2009, and you can say what it says about heavy lifts and home equipment.", [W("Growth spurt", "the years when a young person grows quickly.")]),
      S("Ask a coach or athletic trainer for your plan", OWN + "The pages above do not set a plan for your sport. A coach or athletic trainer who knows your sport can. Write down your age, your sport, how many days you train now, and your questions, and bring them to the person who will set your plan.", ["Paper and a pen", "The name of your coach or athletic trainer"], null, "you have a page with your age, sport and training days, and the name of the person you will ask.", [W("Athletic trainer", "a health professional who works with a team on injury prevention and care.")])
    ]
  },

  "sleep-rest-and-a-strained-muscle": {
    title: "Sleep, rest days, overuse and a strained muscle",
    topic: "athlete-recovery", phrase: "resting, sleeping and recovering from a strained muscle as an athlete",
    steps: [
      S("Check how much sleep you need", "The CDC's sleep table says teens aged 13 to 17 need 8 to 10 hours, and adults aged 18 to 60 need 7 or more. Find your age, then count back from the time you wake up to find your bedtime.", ["The time you wake up on school or work days", "Paper and a pen"], "cdcSleep", "you know your age group's hours and have worked out a bedtime.", [W("Sleep table", "a chart that shows how many hours of sleep each age group needs.")]),
      S("Learn what sleep does for an athlete", "An NCAA sheet recommends 8 hours for college athletes. It says athletes who do not sleep enough have a higher risk of muscle and bone injury and slower recovery after injury.", ["The official page open to read"], "ncaaSleep", "you can name two things the NCAA says poor sleep does to an athlete.", [W("NCAA", "the National Collegiate Athletic Association, which runs most college sports in the United States.")]),
      S("Plan rest days and time off", "The American Academy of Pediatrics says young athletes need one to two rest days a week and two to three months off during the year. It also says weekly training hours should not exceed the child's age. Put your rest days on the calendar first, before the training.", ["A calendar"], "aapBurnout", "you have marked at least one rest day each week on your calendar.", [W("Burnout", "feeling worn out and losing interest in your sport after too much training or pressure.")]),
      S("Watch for overuse", "An older 2011 handout from the American Academy of Pediatrics describes overuse injury in four stages, from pain after activity to constant pain even at rest. It says to increase weekly training by no more than 10 percent. If you notice these stages in yourself, ask a doctor.", ["The official handout open to read", "Your training hours for last week"], "aapOveruse", "you can say the first and last of the four stages, and you have worked out the most your training could rise next week.", [W("Overuse injury", "an injury that builds up over time from doing the same movement too much.")]),
      S("Know what the page says about a hamstring strain", "AAOS OrthoInfo says a hamstring strain is common in sprinters. Grade 1 is mild, and grade 3 is a complete tear that can take months to heal. It says people often see a doctor for sudden pain in the back of the thigh during exercise, and that an exam and imaging show how bad it is. Return to sport only with a doctor's approval.", ["The official page open to read"], "orthoHamstring", "you know to see a doctor for sudden pain in the back of the thigh, and not to return to sport until a doctor approves.", [W("Hamstring", "the muscles at the back of your thigh."), W("Strain", "a stretched or torn muscle.")]),
      S("Do not wait on me for danger signs", "The pages I read do not list signs that mean see a doctor right away. So if an injury is severe, or you are worried, do not wait: call your doctor, or the emergency number if it is an emergency. " + OWN + "Write down where and when it hurt, what you were doing, and what makes it better or worse, to tell the doctor.", ["Paper and a pen", "The phone number of your doctor or clinic"], "medlineStrains", "you have your doctor's number written down, and notes about the injury if you have one.", [])
    ]
  },

  "after-a-blow-to-the-head": {
    title: "What to do after a blow to the head in sport",
    topic: "athlete-concussion", phrase: "what to do after a blow to the head in sport",
    steps: [
      S("Know when to call 911", "After a bump, blow or jolt to the head, the CDC says to call 911 or go to the nearest emergency department for any danger sign. The signs are seizures, not recognizing people or places, repeated vomiting, increasing confusion or agitation, loss of consciousness or being unable to wake, slurred speech, weakness or numbness, a headache that gets worse and does not go away, or one pupil larger than the other.", ["The official page open to read"], "cdcHeadsSigns", "you can name at least four danger signs, and you know to call 911 if any of them happens.", [W("Emergency department", "the part of a hospital that treats serious injuries and sudden illness."), W("Pupil", "the black circle in the middle of the eye.")]),
      S("Know what a concussion is", "The CDC says a concussion is a brain injury from a bump, blow or jolt to the head, or from a hit to the body that moves the head and brain fast. Symptoms can take hours or days to appear. I cannot tell you whether anyone has a concussion. Only a health care provider can.", ["The official page open to read"], "cdcHeadsBasics", "you can say that symptoms can show up hours or days later.", [W("Concussion", "a brain injury caused by a blow or jolt to the head or body.")]),
      S("Have a health care provider check", "Unless there are danger signs, the CDC says to have a health care provider check the person within the first 24 to 48 hours. It says to limit screens and hard activity for the first day or two, and that light activity such as short walks is fine. The person should not return to sport until a provider approves.", ["The phone number of a doctor or clinic"], "cdcHeadsRecovery", "you have called or planned a visit with a health care provider within 24 to 48 hours.", [W("Health care provider", "a doctor, nurse or other licensed professional who treats patients.")]),
      S("Return to sport in six steps", "The CDC's return-to-sport plan has six steps: regular activities, light aerobic activity, moderate activity, heavy non-contact activity, full-contact practice, and then competition. Each step takes at least 24 hours. If symptoms come back, the person stops and goes back a step.", ["The official page open to read", "Paper and a pen"], "cdcHeadsReturn", "you have written down the six steps in order.", [W("Non-contact", "training where players do not hit or tackle each other.")]),
      S("Know how long it can take and what the pages do not say", "The CDC says most children feel better in 2 to 4 weeks. These pages are written for parents of children and do not address professional athletes separately. Ask the provider what fits your own case.", ["Paper and a pen for your questions"], "cdcHeadsRecovery", "you have two or three questions written down for the provider.", []),
      S("If you coach youth sports, take the free training", "The CDC offers free online concussion training for youth sports coaches. If you coach, take it, so you know the signs before you need them.", ["A computer or phone"], "cdcHeadsCoaches", "you have opened the training page, or you know you are not a coach and can skip this step.", [])
    ]
  },

  "staying-safe-in-the-heat": {
    title: "Staying safe when you train or play in the heat",
    topic: "athlete-heat", phrase: "staying safe when an athlete trains in the heat",
    steps: [
      S("Stop and get help at the first warning", "The CDC says muscle cramping may be an early sign of heat illness. Someone who feels faint or weak should stop all activity and get to a cool place. It says to get medical care right away if you or a teammate has symptoms.", ["A cool, shaded place near where you train"], "cdcHeatAthletes", "you can say what to do at the first sign: stop, get to a cool place, and get medical care.", [W("Heat illness", "sickness caused by the body getting too hot, from mild cramps to life-threatening heat stroke.")]),
      S("Know the signs of heat stroke", "The CDC says heat stroke is the most serious, with confusion, slurred speech, passing out, seizures, or very high body temperature, with hot dry skin or heavy sweating. It can be fatal if treatment is delayed. Call 911, stay with the person, and move them to a cool shaded place. The page also says to cool them quickly with cold water or cold wet cloths on the head, neck, armpits and groin.", ["The official page open to read"], "cdcHeatIllness", "you know that heat stroke means calling 911 and staying with the person.", [W("Heat stroke", "the most serious heat illness. The body cannot cool itself, and it can be fatal.")]),
      S("Know heat exhaustion and heat cramps", "For heat exhaustion, with headache, nausea, dizziness, weakness and heavy sweating, the CDC says to get a medical evaluation, move out of the heat and sip cool water. For heat cramps it says drink water and a sports drink or a snack with carbohydrates and electrolytes every 15 to 20 minutes, and avoid salt tablets. Get medical help if cramps do not go away within an hour.", ["The official page open to read"], "cdcHeatIllness", "you can say the signs of heat exhaustion and when cramps need medical help.", [W("Heat exhaustion", "a heat illness with headache, nausea, dizziness, weakness and heavy sweating."), W("Electrolytes", "salts in your body, like sodium and potassium, that you lose when you sweat.")]),
      S("Drink before you are thirsty", "The CDC says to drink more water than usual in the heat and not to wait until you are thirsty. Keep a bottle with you.", ["A water bottle"], "cdcHeatAthletes", "you have a bottle ready, and you know to drink before you feel thirsty.", []),
      S("Give your body time to get used to heat", "The National Athletic Trainers' Association says athletes should be acclimatized over 7 to 14 days. It says for heat stroke, cool first and transport second, but that is for medical staff, not for an athlete to do alone. Ask your coach or athletic trainer how your team builds up.", ["Your training schedule", "The name of your coach or athletic trainer"], "nataHeat", "you know acclimatizing takes 7 to 14 days, and you have asked your coach or trainer how your team does it.", [W("Acclimatized", "slowly used to hot weather over several days.")]),
      S("Make a hot-day plan with your team", OWN + "Before the next hot practice, write down where the shade is, where the water is, who has a phone, and the emergency number, which is 911 in the United States. Tell a teammate or the coach your plan.", ["Paper and a pen", "A phone"], null, "you have a short written plan and a coach or teammate knows it.", [])
    ]
  },

  "pressure-stress-and-mental-health": {
    title: "Handling pressure, stress and mental health as an athlete",
    topic: "athlete-mental", phrase: "handling pressure and stress as an athlete",
    steps: [
      S("Know who to call or text right now", "That sounds like a heavy thing to carry, and asking about it is a good step. In the United States you can call or text 988, or chat online, any time, free and confidential. The pages say you do not have to be suicidal to call, and that reasons include depression, loneliness and relationships. If life is in danger, call 911.", ["A phone", "Paper to write the number on"], "lifeline988", "you have 988 saved in your phone or written where you can find it.", [W("988", "the free phone and text number for mental health crisis support in the United States.")]),
      S("Notice what you are feeling", "The National Institute of Mental Health says to seek professional help when symptoms are severe or distressing or last two weeks or more. It lists sleep problems, changes in appetite, trouble concentrating, or loss of interest. Write down what you notice and when it started. This is not a diagnosis. It is a note to share.", ["Paper and a pen"], "nimhCaring", "you have written what you notice and about when it began.", []),
      S("Start with a primary care provider", "The National Institute of Mental Health says to start with a primary care provider, who can refer you. A team doctor or school counselor is also a good person to ask. Bring your notes.", ["Your notes", "The name of your doctor, team doctor or counselor"], "nimhCaring", "you have picked one person to ask and know how you will reach them.", [W("Primary care provider", "the doctor or nurse you see first for most health needs, who can send you to a specialist.")]),
      S("Try the steady habits the page lists", "The National Institute of Mental Health lists steady sleep, exercise, breathing and relaxation, and learning to say no when you are overloaded. Pick one to try this week.", ["Paper and a pen"], "nimhCaring", "you have chosen one habit and written when you will do it this week.", []),
      S("Use the school and league supports", "The NCAA's mental health best practices say schools should screen athletes for distress at least once a year. The page lists the NAMI HelpLine at 1-800-950-6264, and the Trevor Project for LGBTQ young people at 1-866-488-7386. Ask your school what it offers.", ["A phone", "Your school's athletic department contact"], "ncaaMentalHealth", "you have written down one number from the page, or the name of the person at your school to ask.", [W("NAMI", "the National Alliance on Mental Illness, a group that offers help and information on mental health.")]),
      S("Know what the pages do not say", "The pages I read do not speak to performance pressure in sport in particular, and none addresses professional athletes. A team doctor, school counselor or therapist is the person to ask about pressure in your sport.", ["The name of one person you could ask"], "ncaaMentalHealth", "you can name the person you will ask about pressure in your sport.", [W("Therapist", "a trained professional you talk with about your feelings and problems.")])
    ]
  },

  "reporting-abuse-in-sport": {
    title: "Reporting abuse or misconduct in sport",
    topic: "athlete-safesport", phrase: "reporting abuse or misconduct by a coach in sport",
    steps: [
      S("Call the SafeSport line or 911", "If anyone is in danger right now, call 911. To report abuse or misconduct in the United States Olympic and Paralympic movement, the U.S. Center for SafeSport takes calls at 833-587-7233, Monday to Friday, 6 a.m. to 6 p.m. Mountain Time. It also has an online form, which allows anonymous reports. RAINN's line, which the Center lists, is 1-800-656-4673.", ["A phone", "Paper to write the numbers on"], "safesportReport", "you have the numbers saved or written down, and you know 911 is for danger right now.", [W("SafeSport", "the U.S. Center for SafeSport, which takes reports of abuse and misconduct in Olympic and Paralympic sport."), W("Anonymous", "without giving your name.")]),
      S("Know who can report", "The Center says anyone can report, including parents and coaches, and you do not have to be the athlete. If you saw or heard something that worried you, you can tell the Center.", ["The official page open to read"], "safesportReport", "you can say that anyone, not only the athlete, can make a report.", []),
      S("Tell local authorities too if a child may be hurt", "If you suspect child abuse or neglect, the Center says to report it to local authorities in addition to, and before, reporting it to the Center. In an emergency, call 911. The guide does not say what the number for local authorities is where you live; ask your local police.", ["The phone number of your local police"], "safesportReport", "you know that suspected child abuse goes to local authorities first and then to the Center.", [W("Neglect", "when a child is not given the care and safety they need.")]),
      S("Know what else you can report", "Emotional and physical misconduct, such as bullying, hazing and harassment, can also be reported to the Center or to the sport's national governing body.", ["The official page open to read"], "safesportReport", "you can name three kinds of misconduct that can be reported besides abuse.", [W("Hazing", "forcing someone to do something humiliating or harmful to join or stay in a group."), W("National governing body", "the organization that runs one sport across the country.")]),
      S("Learn the rules that protect young athletes", "The Center's Minor Athlete Abuse Prevention Policies limit one-on-one interaction between adults and minor athletes. Organizations had to adopt the 2025 version by January 1, 2025. The page I read does not list the specific rules, so I will not describe them. Ask the organization or the Center.", ["The official page open to read"], "safesportMaapp", "you know the policies exist and that you can ask your club or the Center for the exact rules.", [W("Minor athlete", "an athlete under 18.")]),
      S("Know the duty to report", "Under a 2018 federal law, adults authorized to interact with minors or amateur athletes in these organizations must report suspected child abuse to the agency the law designates. The law says as soon as possible means within a 24-hour period.", ["The official page open to read"], "publicLaw115126", "you can say that the law sets a 24-hour period for reporting suspected child abuse.", []),
      S("Write down what happened", OWN + "If you can do so safely, write down dates, places, what was said or done, and who else was there. Keep it in a safe place. Notes can help when you speak to the SafeSport line or the authorities.", ["Paper and a pen, or a private note on your phone"], null, "you have written what you remember, or you have decided to call without notes.", [])
    ]
  },

  "getting-a-name-image-likeness-deal": {
    title: "Getting a name, image and likeness deal as a college athlete",
    topic: "athlete-nil", phrase: "getting a name, image and likeness deal as a college athlete", us: true,
    steps: [
      S("Learn what NIL means", "A name, image and likeness deal, called an NIL deal, is one where you are paid for the use of your name, image and likeness. The NCAA allows this for college athletes when the rules in the next steps are met. You will check them before you sign.", ["The NCAA page open to read"], "ncaaNil", "you can say in your own words what an NIL deal is.", [W("NIL", "name, image and likeness: your name, your picture, and the way you look or sound."), W("Likeness", "the way you look or sound, such as your picture or voice.")]),
      S("Check the deal is allowed", "The NCAA says a deal is allowed when you are paid for the use of your NIL, the deal has a valid business purpose tied to a product, service or public event, and the pay is within a reasonable range for someone of your fame and influence. It says pay-for-play, pay with no required promotional work, and agreements with no defined plan are not allowed.", ["The deal offer in writing", "Paper and a pen"], "ncaaNil", "you have checked the offer against all three requirements and the three things not allowed.", [W("Pay-for-play", "pay just for playing your sport, not for a promotion or appearance.")]),
      S("Talk to your compliance office", "In Division I, compliance is required for eligibility, so talk to your school's compliance office. Check your school's policy and your state's law before you sign. The NCAA says you may use an agent or marketing professional, but before you even agree to representation, ask your compliance office.", ["The deal offer", "The name of your school's compliance office"], "ncaaNil", "you have an appointment or message to the compliance office, with the offer attached.", [W("Compliance office", "the school office that checks that athletes follow the rules."), W("Division I", "the top level of NCAA college sports.")]),
      S("Report deals of 600 dollars or more", "In Division I, deals of 600 dollars or more with outside payors are reported through NIL Go, which the College Sports Commission runs. This is done within five business days of agreeing the payment terms. Smaller deals from the same payor are added up. Ask your compliance office who makes the report at your school.", ["The date you agreed the terms", "The payor's name"], "ncaaHouseQa", "you know the five-business-day deadline and who at your school handles the report.", [W("NIL Go", "the system where Division I athletes report outside deals."), W("Payor", "the company or person paying you.")]),
      S("Know what happens if a deal is not cleared", "If a deal is not cleared, you can revise it with the payor, cancel it and refund, or appeal to a neutral arbitrator. The arbitrator has 45 days, and the decision is final and binding. Going ahead with a deal that was not cleared may bring enforcement, which could include loss of eligibility.", ["The official question-and-answer document open"], "ncaaHouseQa", "you can name your three choices if a deal is not cleared.", [W("Arbitrator", "a neutral person who decides a dispute instead of a court.")]),
      S("If you have not enrolled yet or are transferring", "An April 2025 consent judgment lets prospective and transferring athletes negotiate commercial NIL deals before enrolling at a Division I school. It does not allow pay for athletic performance. Ask the compliance office of the school you are joining.", ["The official page open to read"], "ncaaConsentJudgment", "you can say what a prospective athlete may do and what is still not allowed.", [W("Prospective athlete", "a student who has not yet joined a college team.")]),
      S("If you are in high school", "For high school athletes, NIL rules are set state by state. An NFHS article from 2023 said 30 states and Washington D.C. allowed payments. Check your state high school association before you agree to anything.", ["The name of your state high school association"], "nfhsNil", "you have found your state association and know where to ask.", [W("NFHS", "the National Federation of State High School Associations.")])
    ]
  },

  "taxes-on-what-an-athlete-earns": {
    title: "Understanding taxes on what an athlete earns or is given",
    topic: "athlete-taxes", phrase: "understanding taxes on what an athlete earns", us: true,
    steps: [
      S("Know that NIL pay is generally taxable", "The IRS says income from name, image and likeness deals is generally taxable, including things that are not cash, such as merchandise and gift cards. You report all of it, even if the payer sends no form.", ["A list of every deal and gift you received this year"], "irsNil", "you have a list of what you were paid or given, including items that were not cash.", [W("IRS", "the Internal Revenue Service, the United States tax agency."), W("NIL", "name, image and likeness: pay for the use of your name, picture or fame.")]),
      S("Know the form you may receive", "The IRS says a payer sends a Form 1099-NEC for payments of 2,000 dollars or more for payments received in 2026. Keep your own record whether or not you get one, because you report all of it.", ["The forms you have received"], "irsNil", "you can say what a 1099-NEC is and that you report income even without one.", [W("Form 1099-NEC", "a form a payer sends to show how much they paid you for work you did as a self-employed person.")]),
      S("Plan for estimated tax", "The IRS says self-employed athletes usually have no tax withheld, and may need to pay estimated tax with Form 1040-ES. That means you may pay tax during the year, not only at the end. Ask a tax professional whether this applies to you.", ["Your list of income"], "irsEstimatedTaxes", "you know whether you might need to pay estimated tax, or you have written down that you will ask a tax professional.", [W("Withheld", "taken out of your pay by an employer before you get it."), W("Estimated tax", "tax you pay during the year on income that has no tax taken out.")]),
      S("Know self-employment tax", "Self-employment tax is 15.3 percent, made up of 12.4 percent for Social Security and 2.9 percent for Medicare. The IRS says you usually owe it when net self-employment earnings are 400 dollars or more.", ["Your list of income"], "irsSelfEmploymentTax", "you can say the 15.3 percent figure and the 400 dollar line.", [W("Self-employment tax", "the Social Security and Medicare tax paid by people who work for themselves.")]),
      S("Keep receipts and travel logs", "The IRS says to keep receipts and travel and mileage logs, since costs of earning NIL income may be deductible. Travel away from home for business can be deducted if it is ordinary and necessary. A tax professional can say whether a cost counts.", ["A folder or envelope for receipts", "A notebook or phone notes for mileage"], "irsTravel", "you have a place where you keep receipts and a log of trips for deals.", [W("Deductible", "a cost you may subtract from your income before tax is figured.")]),
      S("Track the states where you perform", "The IRS says to track where you perform, because you may owe state tax where you earn income. Its Taxpayer Advocate page says states where an athlete plays or makes appearances could tax a portion. The pages I read do not cover professional athletes or any state's rules, so ask a tax professional.", ["A list of the places where you played or made appearances"], "taxpayerAdvocateNil", "you have a list of the states where you earned money this year.", []),
      S("Know how scholarships are taxed", "The IRS says the part of a scholarship that pays tuition and required fees and books is tax free for a degree candidate. The part for room and board, travel, or payment for required services is taxable. Athletic scholarships follow the same rules.", ["Your scholarship letter"], "irsScholarships", "you have marked in your scholarship letter which parts are tuition, fees and books, and which are not.", [W("Degree candidate", "a student working toward a college degree.")]),
      S("Ask a tax professional who knows athletes", "The guide also says NIL income counts on the FAFSA and could affect aid. Everything here is general information. A tax professional who knows athletes can look at your own papers, so take your lists, forms and receipts.", ["Your lists, forms and receipts", "The name of a tax professional"], "taxpayerAdvocateNil", "you have named who you will ask and have gathered your papers in one place.", [W("FAFSA", "the Free Application for Federal Student Aid, the form used to apply for aid for college.")])
    ]
  },

  "endorsements-and-protecting-your-name": {
    title: "Endorsements, disclosures and protecting your name",
    topic: "athlete-brand", phrase: "endorsements, disclosures and protecting your name as an athlete", us: true,
    steps: [
      S("Know when you must disclose", "The FTC says to disclose any financial, employment, personal or family tie to a brand, including free or discounted products, even if the brand did not ask you to post. To disclose means to tell your audience plainly about the tie.", ["The FTC page open to read"], "ftcDisclosures101", "you can name three kinds of tie to a brand that should be disclosed.", [W("FTC", "the Federal Trade Commission, a United States agency that protects buyers."), W("Disclose", "to tell your audience plainly about a tie to a brand.")]),
      S("Know what the FTC says about athletes", "The FTC's question-and-answer page says whether a disclosure is required for an athlete depends on whether a significant share of viewers would know the post is paid. It says this is hard to judge, and the FTC recommends disclosing.", ["The FTC question-and-answer page open"], "ftcGuidesQuestions", "you can say why the FTC recommends disclosing.", []),
      S("Use words that are clear", "The FTC gives clear examples, such as the word Ad, hashtag ad, and Sponsored by the brand. It says wording like hashtag ambassador, Gifted, or a bare thank you is not enough.", ["A draft of your post"], "ftcDisclosures101", "you have chosen the exact words you will use, and they come from the clear examples.", []),
      S("Put the disclosure where it will be seen", "Put the disclosure at the start of the post. In a video, say it and show it. Do not rely on a platform's tool alone. You are responsible for your own disclosures, and you cannot describe an experience with a product you have not tried.", ["A draft of your post or video"], "ftcDisclosures101", "your draft has the disclosure at the start, and says only what you have really tried.", []),
      S("Learn what a trademark is", "To protect a name or logo, the USPTO says a trademark identifies your goods or services and does not give exclusive rights to a word in general. You can use the TM symbol without filing. The registered symbol is allowed only after federal registration. Registration gives nationwide rights.", ["The USPTO page open to read"], "usptoWhatIs", "you can say the difference between using the TM symbol and having a registered mark.", [W("USPTO", "the United States Patent and Trademark Office."), W("Trademark", "a word, name or logo that shows who a product or service comes from.")]),
      S("Check first, and consider an attorney", "The USPTO says to check whether your mark can be registered before applying, and to search its database first. It strongly encourages an attorney.", ["The name or logo you want to protect", "The USPTO process page open"], "usptoProcess", "you have searched the database for your name, or you have decided to ask an attorney first.", [W("Attorney", "a lawyer, a professional trained in the law.")]),
      S("Watch for trademark scams", "The USPTO warns about scam trademark offers. Start from the official government site, not from an email or a call that came to you.", ["The USPTO scam page open"], "usptoScams", "you can say where to start a trademark search safely.", [])
    ]
  },

  "starting-a-training-business": {
    title: "Starting a business such as a training academy or camp",
    topic: "athlete-business", phrase: "starting a training academy or camp as an athlete", us: true,
    steps: [
      S("Choose how the business is set up", "The Small Business Administration says a sole proprietorship is easy to form but does not separate your business and personal assets, so you can be personally liable. An LLC protects personal assets in most instances and is formed by filing with your state. Think about which fits.", ["The SBA page open to read", "Paper and a pen"], "sbaStructure", "you can say the main difference between a sole proprietorship and an LLC.", [W("Sole proprietorship", "a business owned by one person, with no legal line between the person and the business."), W("LLC", "limited liability company: a business form that can protect your personal assets.")]),
      S("Register the business name", "The SBA says registering the business name protects it at the state level. A trade name, also called a DBA, is registered with the state, county or city. It says registration costs are usually under 300 dollars, and vary by state.", ["Two or three name ideas", "Your state's business office page"], "sbaRegister", "you know where your state registers business names.", [W("DBA", "doing business as: a name you trade under that is not your own legal name.")]),
      S("Think about a federal trademark", "A federal trademark protects a name nationwide, while registering the name with your state protects it at the state level. Look at the USPTO page to see what a trademark is, and think about whether the name matters enough to your plans.", ["Your business name idea"], "usptoWhatIs", "you can say what a federal trademark protects that a state registration does not.", [W("Trademark", "a word, name or logo that shows who a product or service comes from.")]),
      S("Get an employer identification number", "The IRS says an employer identification number, called an EIN, is free, and to beware of websites that charge for one. Go to the IRS page yourself. The guide does not say whether your business needs one, so ask the IRS or a tax professional.", ["The IRS page open", "Your business name"], "irsEin", "you know whether you need an EIN, and that you will never pay a website for one.", [W("EIN", "employer identification number: a number the IRS gives a business.")]),
      S("Find out which licenses and permits you need", "The SBA says most businesses need federal, state or local licenses or permits, and to check with your Secretary of State and local government. Its pages do not mention sports, camps or youth programs in particular, so ask your state and city what a training academy or camp needs.", ["The SBA page open", "The name of your city and state"], "sbaLicenses", "you have the offices to ask written down, and your question about a training academy or camp.", [W("Permit", "official permission to run an activity, given by a city, county or state.")]),
      S("Look at business insurance", "The SBA lists general liability insurance, for bodily injury and property damage, and professional liability insurance, for errors in a service business. Ask an insurance professional which fits your plans.", ["The SBA insurance page open"], "sbaInsurance", "you can name the two kinds of insurance and what each covers.", [W("Liability insurance", "insurance that pays when someone says your business hurt them or damaged their property.")]),
      S("If you will coach children, learn about safe sport", "The U.S. Center for SafeSport's Minor Athlete Abuse Prevention Policies limit one-on-one interaction between adults and minor athletes in the Olympic and Paralympic movement. The guide does not say whether they apply to your business. Ask the Center, and ask me about safe sport.", ["The official page open"], "safesportMaapp", "you know you should ask the Center whether the policies apply to your business.", [])
    ]
  },

  "the-prohibited-list": {
    title: "Finding out what is on the prohibited list",
    topic: "athlete-prohibited", phrase: "finding out what is on the prohibited list as an athlete",
    steps: [
      S("Learn what the list is", "The World Anti-Doping Agency's own page says the prohibited list says what substances and methods are banned in sport and when. It is updated at least annually, published in October and in force on 1 January. A substance can be listed if it meets any two of three tests: it may enhance performance, it is a health risk, or it violates the spirit of sport.", ["The WADA page open to read"], "wadaList", "you can say when the list comes out and when it takes effect.", [W("WADA", "the World Anti-Doping Agency, which sets the global rules on banned substances."), W("Prohibited list", "the official list of substances and methods athletes may not use.")]),
      S("Know the groups on the list", "WADA says categories include anabolic agents, peptide hormones, hormone modulators, diuretics and masking agents, and blood and gene manipulation, which are banned at all times. Stimulants, narcotics, cannabinoids and glucocorticoids are banned in competition. Beta-blockers are banned in particular sports.", ["The WADA page open"], "wadaList", "you can say which groups are banned at all times and which in competition only.", [W("In competition", "during the event period, not in training."), W("Masking agent", "a substance used to hide another banned substance.")]),
      S("Know what the page says about cannabis and CBD", "WADA says all natural and synthetic cannabinoids are prohibited except cannabidiol, called CBD. But some CBD oils may also contain THC and could cause a positive test.", ["The WADA page open"], "wadaList", "you can say why a CBD oil could still cause a positive test.", [W("Cannabinoid", "a chemical found in or made like the cannabis plant."), W("THC", "the part of cannabis that causes a high.")]),
      S("Know the strict liability rule", "WADA says a substance labelled specified does not relieve an athlete of the strict liability rule, which makes the athlete responsible for all substances that enter their body. It names clenbuterol as prohibited at all times with no threshold, and says methylhexaneamine is a constituent of some dietary supplements.", ["The WADA page open"], "wadaList", "you can say in your own words that you are responsible for what is in your body.", [W("Strict liability", "the rule that you are responsible for any banned substance found in you, whether you meant to take it or not.")]),
      S("Know what WADA says about steroid medicines", "WADA says glucocorticoids by injection, mouth or rectum are banned in competition, with washout periods that depend on the drug, and may need a therapeutic use exemption. Ask your team doctor about this before you accept any such medicine.", ["The WADA page open"], "wadaList", "you know these medicines can be banned in competition and may need an exemption.", [W("Glucocorticoid", "a kind of steroid medicine used to reduce swelling."), W("Washout period", "the time a drug must be out of your body before you compete.")]),
      S("Check a medicine before you take it", "WADA says that before taking any medication, an athlete must check its status on the list or with their anti-doping organization. If it is prohibited, you apply for an exemption to your anti-doping organization, not to WADA. Global DRO shows whether a medicine is prohibited, but it holds no information on supplements.", ["The name of the medicine on its box", "The Global DRO page open"], "globalDro", "you know how to look up a medicine and who you apply to for an exemption.", [W("Therapeutic use exemption", "permission to use a prohibited medicine you need for a medical reason."), W("Anti-doping organization", "the body that tests and rules for your sport or country.")]),
      S("Ask the right people", "The guide does not say whether a particular substance is on the list, because the list was not read substance by substance. Your anti-doping organization, Global DRO for medicines, or your team doctor can tell you. I cannot say that a product or medicine is allowed for you.", ["The names of the products or medicines you want to ask about"], "usadaProhibitedList", "you have a short list of your questions and who you will ask.", [])
    ]
  },

  "the-naia-route": {
    title: "Understanding NAIA fees, eligibility, amateurism and aid",
    topic: "athlete-naia", phrase: "understanding NAIA fees, eligibility and aid", us: true,
    steps: [
      S("Register with the NAIA Eligibility Center", "The NAIA says every athlete must register with the NAIA Eligibility Center before competing. The NAIA has its own rules, fees and scholarship limits, separate from the NCAA. Register through the official PlayNAIA site.", ["The PlayNAIA page open"], "naiaExplore", "you know registration happens on the official site, before you compete.", [W("NAIA", "the National Association of Intercollegiate Athletics, a group of colleges that play sports."), W("Eligibility Center", "the office that decides whether a student may play in college.")]),
      S("Find the fee for your kind of student", "The pages list a one-time, nonrefundable registration fee of 110 dollars for a U.S. or Canadian student who enrolls full time right after high school. It is 145 dollars for a student with a break after high school, 160 dollars for a transfer with any college enrollment, and 170 dollars for an international student. A different fee can apply if your student type changes.", ["Your school history", "Paper and a pen"], "naiaExplore", "you have worked out which student type you are and written down its fee.", [W("Nonrefundable", "you will not get the money back.")]),
      S("Ask for a fee waiver if you qualify", "A U.S. student can ask for a fee waiver through the NAIA high school portal if they received an SAT or ACT fee waiver or use the free or reduced-price lunch program. Your school counselor can help you ask.", ["Proof of your SAT or ACT fee waiver, or lunch program status", "The name of your school counselor"], "naiaFeeWaiver", "you know whether you qualify, and have asked your counselor if you do.", [W("Fee waiver", "permission not to pay a fee because of your family's situation.")]),
      S("Check the academic rules", "For an entering freshman, the NAIA's 2026-27 handbook says a student is eligible with an overall high school GPA of 2.300 or higher on a 4.000 scale. Or you can meet two of three: an ACT of 18 or an SAT of 970, a GPA of 2.000, or a rank in the upper half of the class. The NAIA says no core courses are necessary.", ["Your high school grades", "Your test scores, if you have them"], "naiaHandbook", "you have compared your own GPA and scores with the two ways to be eligible.", [W("GPA", "grade point average: your average grade on a scale, here out of 4.000."), W("Core courses", "a set of school subjects some other groups require. The NAIA says none are necessary.")]),
      S("Keep your amateur standing", "The handbook says only amateurs are eligible. A student loses amateur standing by taking expense reimbursement beyond actual travel, meals and lodging, signing a contract with a professional team, or competing as a professional.", ["The handbook page open"], "naiaHandbook", "you can name the three things that cost a student amateur standing.", [W("Amateur", "an athlete who does not take pay for playing.")]),
      S("Learn how athletic aid and transfers work", "The handbook says NAIA schools may give athletics aid, no more than the actual cost of tuition, fees, books and room and board. Each sport has an overall limit. A transfer is not required to sit out a residency period, though conference rules may apply.", ["The handbook page open"], "naiaHandbook", "you can say the most athletics aid can cover, and that a transfer need not sit out under NAIA rules.", [W("Residency period", "a waiting time before a transfer student may play.")]),
      S("Confirm the numbers each year", "These fees and thresholds are updated every year. Confirm on PlayNAIA before you rely on them.", ["The PlayNAIA page open", "Today's date"], "naiaExplore", "you have checked the current year's fee and rules on the official site.", [])
    ]
  },

  "keeping-amateur-status": {
    title: "Keeping amateur status in college sports",
    topic: "athlete-amateurism", phrase: "keeping amateur status in college sports", us: true,
    steps: [
      S("Learn what costs amateur status", "The NCAA's Division I bylaw 12.1.2, in an exam-resource excerpt, says a person loses amateur status by using athletics skill for pay in any form, accepting a promise of pay, or signing a professional contract. Taking a salary or expenses from a professional organization, competing on a professional team, entering a professional draft after enrolling, or agreeing to be represented by an agent also counts. The text I read predates some 2026 changes.", ["The NCAA page open to read"], "ncaaAgentBylaws", "you can name at least four things that cost amateur status under that bylaw.", [W("Amateur status", "being treated as an athlete who plays for school and not for pay."), W("Bylaw", "a written rule of the NCAA.")]),
      S("Know the rules on prize money and tryouts", "A Division I summary for 2024-25 says prize money outside tennis may not exceed 300 dollars above actual and necessary expenses. In tennis, before enrollment, up to 10,000 dollars per calendar year is allowed. The NCAA says one 48-hour tryout per team after enrolling is allowed with expenses, without missing class.", ["The summary page open"], "ncaaD1Summary", "you can say the prize money limit and the length of an allowed tryout.", [W("Prize money", "money won in a contest or event."), W("Tryout", "a chance to show your skills to a professional team.")]),
      S("See what changed for 2026-27 prospects", "The NCAA said in April 2026 that prospects enrolling in 2026-27 may now sign with professional sports agents before enrolling, accept prize money in their sport, and enter a draft once, without it affecting eligibility. The rule after enrollment is unchanged. Confirm your own case with your compliance office.", ["The NCAA news page open"], "ncaaProspects2026", "you can say that the change is for prospects before enrolling and not for athletes already enrolled.", [W("Prospect", "a student who plans to play in college but has not enrolled yet."), W("Compliance office", "the school office that makes sure athletes follow the rules.")]),
      S("Read the basketball draft rules", "The NCAA's March 2026 memo says a men's basketball player keeps eligibility if he asks for an NBA Undergraduate Advisory Committee evaluation, asks to be removed from the draft, tells his athletic director in writing within 10 days after the draft combine, and is not drafted. Memos are for particular draft years, and dates change.", ["The memo open to read", "The date of this year's combine"], "ncaaNbaMemo", "you have written the steps in order, with the 10-day line after the combine.", [W("Draft", "the event where professional teams pick players."), W("Draft combine", "an event where players are tested and watched by professional teams.")]),
      S("Read the football draft rules", "The NCAA's December 2025 football memo says an athlete three years out of high school may enter once and keep eligibility if he is not drafted and declares his intent to resume play within 72 hours. It says no to any agreement with an agent or runner. Contact alone is not prohibited if there is no agreement and no benefits.", ["The memo open to read"], "ncaaNflMemo", "you can say the 72-hour line and what the memo says about agreements.", [W("Runner", "a person who steers athletes toward an agent.")]),
      S("Read the baseball draft rules", "The NCAA's 2024 baseball memo says a draft does not by itself end eligibility, and a drafted player who does not sign can return. Ask your compliance office about agents and contracts before you talk to anyone.", ["The memo open to read"], "ncaaMlbMemo", "you can say that a draft alone does not end eligibility in baseball.", []),
      S("Confirm with the Eligibility Center or your compliance office", "The Eligibility Center reviews academic records and athletics-related activities. The pages I read do not give a plain-language amateurism guide, and the summary is for 2024-25, so please confirm with the Eligibility Center or your compliance office before you accept money, sign with anyone, or enter a draft.", ["Your questions written down", "The name of your compliance office"], "ncaaRegister", "you have a written question for the Eligibility Center or compliance office, and you know how to send it.", [W("Eligibility Center", "the NCAA office that reviews whether a student may play in college.")])
    ]
  }
};
